app.use(limiter);

// Or apply to specific routes:
app.use('/users', limiter);
```

#### 4. Missing CORS Policy (**OWASP A05:2021 - Security Misconfiguration**)
No CORS configuration is present, which could lead to unintended cross-origin requests.

**Risk Level:** Low-Medium (depending on deployment context)

**Current Code:** No CORS headers set

**Recommendation:** Configure appropriate CORS policy.

**Fixed Code:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));

// Or for more restrictive settings:
app.use(cors({
  origin: ['https://your-trusted-domain.com'],
  methods: ['GET'],
  credentials: false
}));
```

#### 5. No Error Handling for Sensitive Information Exposure (**OWASP A09:2021 - Security Logging and Monitoring Failures**)
The application doesn't have proper error handling that could leak stack traces or other sensitive information.

**Risk Level:** Low (in current implementation) but could become high

**Current Code:** No centralized error handling

**Recommendation:** Implement proper error handling middleware.

**Fixed Code:**
```javascript
// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // In production, don't leak error details
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(status).json({ error: message });
});

// Handle async errors
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});
```

#### 6. Missing Authentication and Authorization (**OWASP A01:2021 - Broken Access Control**, **A07:2021 - Identification and Authentication Failures**)
The `/users` endpoint exposes user data without any authentication or authorization checks.

**Risk Level:** High (if this were real user data)

**Current Code:** Public access to user data

**Recommendation:** Implement authentication middleware for sensitive endpoints.

**Example Fix:**
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401);

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

// Protect sensitive endpoints
app.get('/users', authenticateToken, (req, res) => {
  // Only return data that the authenticated user is allowed to see
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

#### 7. Use of Hardcoded Secrets (Potential Issue)
While not directly in app.js, the presence of the `.env.test` file with canary values indicates potential secret management issues.

**Risk Level:** Low (these appear to be test canary values)

